<?php require __DIR__.'/bootstrap.php';require_login();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='save'){$name=trim((string)($_POST['area_name']??''));$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['active'])?1:0;if($name!==''){if($id)$pdo->prepare('UPDATE service_areas SET area_name=?,sort_order=?,active=? WHERE id=?')->execute([$name,$sort,$active,$id]);else $pdo->prepare('INSERT INTO service_areas(area_name,sort_order,active) VALUES(?,?,?)')->execute([$name,$sort,$active]);flash('success','Service area saved.');}}elseif($a==='delete'&&$id){$pdo->prepare('DELETE FROM service_areas WHERE id=?')->execute([$id]);flash('success','Service area deleted.');}header('Location: areas.php');exit;}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM service_areas WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT * FROM service_areas ORDER BY sort_order,id')->fetchAll();$pageTitle='Service Areas';$active='areas';require __DIR__.'/_header.php';?>
<div class="page-heading"><div><p class="eyebrow">SERVICE AREAS</p><h1>Coverage locations</h1><p class="muted">Manage cities, areas or ZIP codes shown on the public landing page.</p></div></div><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h((string)($edit['id']??0))?>"><div class="three-col"><label>Area / City / ZIP<input name="area_name" required value="<?=h($edit['area_name']??'')?>"></label><label>Order<input type="number" name="sort_order" value="<?=h((string)($edit['sort_order']??0))?>"></label><label class="check-row status-switch"><input type="checkbox" name="active" <?=!$edit||!empty($edit['active'])?'checked':''?>> Visible</label></div><div class="form-actions"><button>Save area</button><?php if($edit):?><a class="button secondary" href="areas.php">Cancel</a><?php endif;?></div></form></section><div class="list-grid"><?php foreach($rows as $r):?><article class="list-card"><div class="list-head"><div><strong><?=h($r['area_name'])?></strong><small>Order <?=$r['sort_order']?></small></div><span class="badge <?=$r['active']?'contacted':'closed'?>"><?=$r['active']?'Visible':'Hidden'?></span></div><div class="actions"><a class="button secondary small" href="?edit=<?=$r['id']?>">Edit</a><form method="post" data-swal-confirm="Delete this service area?" data-swal-text="This location will no longer appear on the website."><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button danger small">Delete</button></form></div></article><?php endforeach;?></div><?php require __DIR__.'/_footer.php';